import { authorize } from '../security/permissions.js';
import { validate } from '../security/validation.js';
import { requireValue } from '../core/contracts.js';
import { assertCapabilityApproval, isCapabilityApprovalPolicyValid } from '../security/approval-gates.js';

// Health diagnostics are included in API/UI inventory responses. Provider error
// messages can contain URLs, tokens or private account data; expose codes only.
function publicHealthDiagnostic(value, fallback = 'HEALTHCHECK_DETAIL_REDACTED') {
  if (typeof value !== 'string') return fallback;
  const code = value.trim();
  // Two documented Microsoft Graph diagnostics are safe, allowlisted error
  // identifiers (not raw upstream messages). Preserve actionable 403 clues.
  if (/^PIPEDREAM_PROXY_FAILED_HTTP_403_(?:Authorization_RequestDenied|accessDenied)$/.test(code)) return code;
  return /^[A-Z][A-Z0-9_]{0,79}$/.test(code) ? code : fallback;
}

/** Construct per composition root; adapters are trusted server code, never client JS. */
export class CapabilityBus {
  // Requests already dispatched in this runtime, to refuse a replay.
  #dispatched = new Set();
  constructor({audit = async () => {}} = {}) { this.records = new Map(); this.audit = audit; }
  discover(record, execute, healthcheck = null) {
    for (const field of ['id','name','category','version','provider','description','input_schema','output_schema','risk','permissions','health','enabled']) requireValue(record[field] !== undefined, 'INVALID_CAPABILITY');
    requireValue(!this.records.has(record.id) && typeof execute === 'function' && Array.isArray(record.permissions) && typeof record.enabled === 'boolean', 'INVALID_CAPABILITY');
    requireValue(isCapabilityApprovalPolicyValid(record.approval), 'INVALID_CAPABILITY');
    const inlineHealthcheck = record.healthcheck ?? null;
    const resolvedHealthcheck = healthcheck ?? inlineHealthcheck;
    requireValue(resolvedHealthcheck === null || typeof resolvedHealthcheck === 'function', 'INVALID_CAPABILITY');
    const storedRecord = { ...record };
    delete storedRecord.healthcheck;
    this.records.set(record.id, {record: structuredClone(storedRecord), execute, healthcheck: resolvedHealthcheck});
    return this.describe(record.id);
  }
  list() { return [...this.records.values()].map(x => structuredClone(x.record)); }
  search(query) { return this.list().filter(x => `${x.id} ${x.name} ${x.description}`.toLowerCase().includes(String(query).toLowerCase())); }
  describe(id) { const entry = this.records.get(id); requireValue(entry, 'CAPABILITY_NOT_FOUND', 404); return structuredClone(entry.record); }
  health(id) { return this.describe(id).health; }
  contract(id) {
    const entry = this.records.get(id); requireValue(entry, 'CAPABILITY_NOT_FOUND', 404);
    const record = entry.record || {};
    const inputSchemaValid = Boolean(record.input_schema && typeof record.input_schema === 'object' && !Array.isArray(record.input_schema));
    const outputSchemaValid = Boolean(record.output_schema && typeof record.output_schema === 'object' && !Array.isArray(record.output_schema));
    const permissionsValid = Array.isArray(record.permissions) && record.permissions.every(value => typeof value === 'string' && value.trim().length > 0);
    const riskValid = ['LOW','MEDIUM','HIGH'].includes(String(record.risk || '').toUpperCase());
    const healthValid = typeof record.health === 'string' && record.health.trim().length > 0;
    const enabledValid = typeof record.enabled === 'boolean';
    const handlerRegistered = typeof entry.execute === 'function';
    const healthcheckValid = entry.healthcheck === null || typeof entry.healthcheck === 'function';
    const approvalValid = isCapabilityApprovalPolicyValid(record.approval);
    const valid = inputSchemaValid && outputSchemaValid && permissionsValid && riskValid && healthValid && enabledValid && handlerRegistered && healthcheckValid && approvalValid;
    return Object.freeze({
      valid,
      handler_registered: handlerRegistered,
      input_schema_valid: inputSchemaValid,
      output_schema_valid: outputSchemaValid,
      permissions_valid: permissionsValid,
      risk_valid: riskValid,
      health_valid: healthValid,
      enabled_boolean: enabledValid,
      healthcheck_valid: healthcheckValid,
      approval_policy_valid: approvalValid,
      explicit_approval_gate: record.approval?.required === true,
      authorization_gate: true,
      input_validation_gate: true,
      output_validation_gate: true,
    });
  }
  async refreshHealth(id) {
    const entry = this.records.get(id); requireValue(entry, 'CAPABILITY_NOT_FOUND', 404);
    if (!entry.healthcheck) return this.describe(id);
    try {
      const observed = await entry.healthcheck();
      const status = typeof observed === 'string' ? observed : observed?.status;
      const reported = typeof observed === 'object' && observed
        ? (observed.code || observed.reason || observed.detail || '')
        : '';
      const detail = reported ? publicHealthDiagnostic(reported) : '';
      entry.record.health = status === 'ONLINE' || status === 'HEALTHY'
        ? 'HEALTHY'
        : status === 'SAFE_IDLE' || status === 'PROTECTED'
          ? 'PROTECTED'
          : status === 'OFFLINE' || status === 'UNAVAILABLE'
            ? 'UNAVAILABLE'
            : 'DEGRADED';
      if (detail) entry.record.health_detail = detail.slice(0, 240);
      else delete entry.record.health_detail;
    } catch (error) {
      entry.record.health = 'DEGRADED';
      entry.record.health_detail = publicHealthDiagnostic(error?.code, 'HEALTHCHECK_FAILED');
    }
    return this.describe(id);
  }
  async refreshHealthAll() {
    const ids = [...this.records.keys()];
    const concurrency = 6;
    for (let index = 0; index < ids.length; index += concurrency) {
      await Promise.all(ids.slice(index, index + concurrency).map(id => this.refreshHealth(id)));
    }
    return this.list();
  }
  enable(id, context) { authorize(['capabilities.manage'],context); this.records.get(this.describe(id).id).record.enabled = true; }
  disable(id, context) { authorize(['capabilities.manage'],context); this.records.get(this.describe(id).id).record.enabled = false; }
  // Enregistre une capacité manquante ou versionnée sur le bus canonique.
  // Utilisé lorsqu’un écart prouvé ouvre un objectif reprenable.
  // Le handler fourni doit être une fonction async retournant le résultat attendu.
  // Si aucun handler n’est fourni, une erreur générique est levée à l’exécution.
  deliverCapability(id, record, handler = async () => { throw new Error('CAPABILITY_NOT_IMPLEMENTED'); }) {
    if (this.records.has(id)) throw new Error('CAPABILITY_ALREADY_EXISTS');
    const entry = {
      record: { ...record, id, enabled: true },
      execute: handler,
    };
    this.records.set(id, entry);
    return true;
  }
  // MEL-CHAT-08: one execution identifier runs through validation, permission,
  // dispatch, the typed result and the render. Callers read it from
  // executeDetailed(); the audit rows of one call all carry it.
  async executeDetailed(id, input, context = {}) {
    const executionId = /^[0-9a-f-]{8,64}$/i.test(String(context?.executionId || ''))
      ? String(context.executionId) : crypto.randomUUID();
    const output = await this.execute(id, input, { ...context, executionId });
    return { execution_id: executionId, capability: id, output };
  }

  async execute(id, input, context = {}) {
    const entry = this.records.get(id); requireValue(entry, 'CAPABILITY_NOT_FOUND', 404);
    const event = {
      id: /^[0-9a-f-]{8,64}$/i.test(String(context?.executionId || '')) ? String(context.executionId) : crypto.randomUUID(),
      capability: id,
      owner: context?.owner || null,
      requestId: context?.requestId || null,
    };
    // A replayed dispatch must never run the action twice. Opt-in per call:
    // the caller passes an idempotencyKey for an action it must not duplicate.
    // requestId alone is reused legitimately and never arms this guard.
    const replayKey = context?.idempotencyKey ? id + '\u0000' + String(context.idempotencyKey) : '';
    if (replayKey && this.#dispatched.has(replayKey)) {
      await this.audit({ ...event, status: 'DENIED', reason: 'CAPABILITY_REPLAY_REFUSED' });
      throw Object.assign(new Error('CAPABILITY_REPLAY_REFUSED'), { code: 'CAPABILITY_REPLAY_REFUSED', status: 409, execution_id: event.id });
    }
    let record;
    try {
      // Security gates run before any provider/network health probe. This keeps
      // denied or approval-gated actions side-effect free even when a
      // capability has a live healthcheck.
      record = this.describe(id);
      requireValue(record.enabled, 'CAPABILITY_DISABLED', 409);
      authorize(record.permissions,context);
      assertCapabilityApproval(record, context);
      validate(input,record.input_schema);
      if (entry.healthcheck) {
        await this.refreshHealth(id);
        record = this.describe(id);
      }
      // The exact provider reason (e.g. GMAIL_AUTH_REQUIRED) travels with the
      // refusal: MEL-MANIFEST-08 requires the precise error, never a generic one.
      if (record.health === 'UNAVAILABLE') throw Object.assign(new Error('CAPABILITY_UNAVAILABLE'), {
        code: 'CAPABILITY_UNAVAILABLE', status: 503, ...(record.health_detail ? { reason: record.health_detail } : {}) });
    } catch (error) {
      await this.audit({
        ...event,
        status:'DENIED',
        reason:String(error?.code || error?.message || 'CAPABILITY_PREFLIGHT_DENIED').slice(0,120),
      });
      throw error;
    }
    const startedAt = Date.now();
    if (replayKey) this.#dispatched.add(replayKey);
    await this.audit({...event,status:'STARTED'});
    try {
      const output = await entry.execute(input,context);
      // An output that breaks its contract is never a success. The original
      // validation error keeps its code and status; it only gains the facts a
      // caller needs: which execution, and that the action may already have run.
      try { validate(output,record.output_schema); }
      catch (invalid) {
        if (invalid && typeof invalid === 'object') {
          invalid.execution_id = event.id;
          invalid.output_contract_violation = true;
          invalid.action_may_have_run = true;
        }
        throw invalid;
      }
      await this.audit({...event,status:'SUCCEEDED',duration_ms:Math.max(0,Date.now()-startedAt)});
      return output;
    } catch (error) {
      await this.audit({
        ...event,
        status:'FAILED',
        duration_ms:Math.max(0,Date.now()-startedAt),
        error_code:String(error?.code || error?.message || 'CAPABILITY_FAILED').slice(0,120),
      });
      if (error && typeof error === 'object' && !error.execution_id) error.execution_id = event.id;
      throw error;
    }
  }
}

const GMAIL_API = 'https://gmail.googleapis.com/gmail/v1/users/me';
const GMAIL_SEARCH_METADATA_MAX = 10;
const CALENDAR_API = 'https://www.googleapis.com/calendar/v3';
const TASKS_API = 'https://tasks.googleapis.com/tasks/v1';
const MAX_LIST = 50;

function error(code, status = 502) {
  const err = new Error(code);
  err.code = code;
  err.status = status;
  return err;
}

function text(value, code, max = 4000, { required = true } = {}) {
  const normalized = String(value ?? '').trim();
  if (required && !normalized) throw error(code, 400);
  if (normalized.length > max) throw error(code, 400);
  return normalized;
}

function listLimit(value, fallback = 20) {
  const n = Number(value);
  return Number.isInteger(n) ? Math.max(1, Math.min(MAX_LIST, n)) : fallback;
}

function fixedTokenResolver(env = {}) {
  return async connectorId => {
    const keys = {
      gmail: 'GMAIL_ACCESS_TOKEN',
      'google-calendar': 'GOOGLE_CALENDAR_ACCESS_TOKEN',
      'google-tasks': 'GOOGLE_TASKS_ACCESS_TOKEN',
    };
    return String(env[keys[connectorId]] || '').trim();
  };
}

function encodePath(value, code, max = 300) {
  const v = text(value, code, max);
  if (v.includes('/') || v.includes('..')) throw error(code, 400);
  return encodeURIComponent(v);
}

function query(params = {}) {
  const out = new URLSearchParams();
  for (const [key, value] of Object.entries(params)) {
    if (value === undefined || value === null || value === '') continue;
    out.set(key, String(value));
  }
  return out.toString();
}

async function requestJson(fetchImpl, token, url, { method = 'GET', body, code = 'GOOGLE_REQUEST_FAILED', signal } = {}) {
  if (!token) throw error(code.replace(/_FAILED$/, '') + '_AUTH_REQUIRED', 503);
  let response;
  try {
    response = await fetchImpl(url, {
      method,
      headers: {
        authorization: 'Bearer ' + token,
        accept: 'application/json',
        ...(body === undefined ? {} : { 'content-type': 'application/json' }),
      },
      body: body === undefined ? undefined : JSON.stringify(body),
      redirect: 'error',
      signal: signal || AbortSignal.timeout(10000),
    });
  } catch (cause) {
    const kind = String(cause?.name || '');
    // MEL-CHAT-08: a timeout on a non-GET call is not a failure to retry
    // blindly — the write may already have been applied upstream.
    throw Object.assign(
      error(code + (kind === 'TimeoutError' || kind === 'AbortError' ? '_TIMEOUT' : '_NETWORK'), 503),
      { retryable: method === 'GET', action_may_have_run: method !== 'GET' });
  }
  if (response.status === 401 || response.status === 403) {
    await response.body?.cancel?.();
    throw error(code + '_AUTH', 403);
  }
  if (response.status === 429) {
    await response.body?.cancel?.();
    // Quota refused the call outright: nothing ran, so this one is safe to retry.
    throw Object.assign(error(code + '_RATE_LIMITED', 503), { retryable: true, action_may_have_run: false });
  }
  if (!response.ok) {
    await response.body?.cancel?.();
    throw error(code, response.status >= 400 && response.status < 600 ? response.status : 502);
  }
  if (response.status === 204) return {};
  const raw = await response.text();
  if (!raw.trim()) return {};
  try { return JSON.parse(raw); } catch { throw error(code + '_INVALID_RESPONSE', 502); }
}

function safeEmail(value) {
  const email = text(value, 'GMAIL_EMAIL_INVALID', 320);
  if (/[\r\n]/.test(email) || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) throw error('GMAIL_EMAIL_INVALID', 400);
  return email;
}

function safeEmails(values, max = 20) {
  if (!Array.isArray(values) || values.length < 1 || values.length > max) throw error('GMAIL_RECIPIENTS_INVALID', 400);
  return [...new Set(values.map(safeEmail))];
}

function optionalEmails(values, max = 20) {
  if (values == null) return [];
  if (!Array.isArray(values) || values.length > max) throw error('GMAIL_RECIPIENTS_INVALID', 400);
  return [...new Set(values.map(safeEmail))];
}

function header(value, code, max) {
  const v = text(value, code, max);
  if (/[\r\n]/.test(v)) throw error(code, 400);
  return v;
}

function base64UrlUtf8(value) {
  const bytes = new TextEncoder().encode(value);
  let binary = '';
  for (let offset = 0; offset < bytes.length; offset += 8192) {
    binary += String.fromCharCode(...bytes.subarray(offset, offset + 8192));
  }
  return btoa(binary).replaceAll('+', '-').replaceAll('/', '_').replace(/=+$/g, '');
}

function mimeMessage(input) {
  const to = safeEmails(input.to);
  const cc = optionalEmails(input.cc);
  const bcc = optionalEmails(input.bcc);
  const subject = header(input.subject, 'GMAIL_SUBJECT_INVALID', 998);
  const body = String(input.body ?? '');
  if (!body.trim() || body.length > 100000) throw error('GMAIL_BODY_INVALID', 400);
  const lines = [
    'To: ' + to.join(', '),
    ...(cc.length ? ['Cc: ' + cc.join(', ')] : []),
    ...(bcc.length ? ['Bcc: ' + bcc.join(', ')] : []),
    'Subject: ' + subject,
    'MIME-Version: 1.0',
    'Content-Type: text/plain; charset=UTF-8',
    'Content-Transfer-Encoding: 8bit',
    '',
    body,
  ];
  return base64UrlUtf8(lines.join('\r\n'));
}

function calendarEvent(input, { partial = false } = {}) {
  const event = {};
  if (!partial || input.summary !== undefined) event.summary = text(input.summary, 'CALENDAR_SUMMARY_INVALID', 1000, { required: !partial });
  if (input.description !== undefined) event.description = text(input.description, 'CALENDAR_DESCRIPTION_INVALID', 12000, { required: false });
  if (input.location !== undefined) event.location = text(input.location, 'CALENDAR_LOCATION_INVALID', 1000, { required: false });
  if (!partial || input.start !== undefined) event.start = { dateTime: text(input.start, 'CALENDAR_START_INVALID', 80) };
  if (!partial || input.end !== undefined) event.end = { dateTime: text(input.end, 'CALENDAR_END_INVALID', 80) };
  if (input.timeZone) {
    const tz = text(input.timeZone, 'CALENDAR_TIMEZONE_INVALID', 100);
    if (event.start) event.start.timeZone = tz;
    if (event.end) event.end.timeZone = tz;
  }
  if (input.attendees !== undefined) {
    const attendees = optionalEmails(input.attendees, 50);
    event.attendees = attendees.map(email => ({ email }));
  }
  return event;
}

function taskBody(input, { partial = false } = {}) {
  const body = {};
  if (!partial || input.title !== undefined) body.title = text(input.title, 'TASK_TITLE_INVALID', 1024, { required: !partial });
  if (input.notes !== undefined) body.notes = text(input.notes, 'TASK_NOTES_INVALID', 8192, { required: false });
  if (input.due !== undefined) body.due = text(input.due, 'TASK_DUE_INVALID', 80, { required: false });
  if (input.status !== undefined) {
    const status = text(input.status, 'TASK_STATUS_INVALID', 32);
    if (!['needsAction', 'completed'].includes(status)) throw error('TASK_STATUS_INVALID', 400);
    body.status = status;
  }
  return body;
}

async function tokenFor(resolveAccessToken, connectorId, context) {
  const token = String(await resolveAccessToken(connectorId, context) || '').trim();
  if (!token) throw error(connectorId.toUpperCase().replaceAll('-', '_') + '_AUTH_REQUIRED', 503);
  return token;
}

function workspaceHealthcheck(resolveAccessToken, fetchImpl, env, connectorId, { protectedAction = false } = {}) {
  const owner = String(env?.MELITURGOS_USER || 'owner').trim() || 'owner';
  const probe = connectorId === 'gmail'
    ? GMAIL_API + '/profile'
    : connectorId === 'google-calendar'
      ? CALENDAR_API + '/calendars/primary'
      : TASKS_API + '/users/@me/lists?maxResults=1';
  const prefix = connectorId.toUpperCase().replaceAll('-', '_') + '_HEALTH';
  return async () => {
    try {
      const token = await tokenFor(resolveAccessToken, connectorId, { owner });
      await requestJson(fetchImpl, token, probe, { method: 'GET', code: prefix + '_FAILED' });
      return { status: protectedAction ? 'PROTECTED' : 'HEALTHY' };
    } catch (cause) {
      const code = String(cause?.code || cause?.message || prefix + '_FAILED').slice(0, 180);
      const http = Number(cause?.status || 0);
      const unavailable = http === 401 || http === 403 || /AUTH_REQUIRED|_AUTH$/.test(code);
      return { status: unavailable ? 'UNAVAILABLE' : 'DEGRADED', reason: code };
    }
  };
}

const objectOutput = { type: 'object', additionalProperties: true };

async function calendarRequest({
  resolveAccessToken,
  fetchImpl,
  pipedreamRuntime,
  env,
  context,
  url,
  method = 'GET',
  body,
  code,
} = {}) {
  let nativeError = null;
  try {
    const token = await tokenFor(resolveAccessToken, 'google-calendar', context);
    const result = await requestJson(fetchImpl, token, url, {
      method,
      body,
      code,
      signal: context?.signal,
    });
    return { provider: 'google', body: result };
  } catch (error) {
    nativeError = error;
  }

  if (!pipedreamRuntime || typeof pipedreamRuntime.proxy !== 'function') throw nativeError;
  try {
    const proxied = await pipedreamRuntime.proxy({
      owner: context?.owner || env?.MELITURGOS_USER || 'owner',
      app: 'google_calendar',
      url,
      method,
      body,
      signal: context?.signal,
    });
    return { provider: 'pipedream', body: proxied?.body || {} };
  } catch (fallbackError) {
    const combined = error(code + '_ALL_PATHS_FAILED', 503);
    combined.native_code = String(nativeError?.code || nativeError?.message || 'CALENDAR_NATIVE_FAILED').slice(0, 160);
    combined.fallback_code = String(fallbackError?.code || fallbackError?.message || 'CALENDAR_PIPEDREAM_FAILED').slice(0, 160);
    throw combined;
  }
}

function calendarHealthcheck(resolveAccessToken, fetchImpl, env, pipedreamRuntime, { protectedAction = false } = {}) {
  const owner = String(env?.MELITURGOS_USER || 'owner').trim() || 'owner';
  const probe = CALENDAR_API + '/calendars/primary';
  return async () => {
    try {
      const token = await tokenFor(resolveAccessToken, 'google-calendar', { owner });
      await requestJson(fetchImpl, token, probe, { method: 'GET', code: 'GOOGLE_CALENDAR_HEALTH_FAILED' });
      return { status: protectedAction ? 'PROTECTED' : 'HEALTHY', transport: 'google' };
    } catch (nativeError) {
      if (!pipedreamRuntime || typeof pipedreamRuntime.proxy !== 'function') {
        const code = String(nativeError?.code || nativeError?.message || 'GOOGLE_CALENDAR_HEALTH_FAILED').slice(0, 180);
        return { status: 'UNAVAILABLE', reason: code };
      }
      try {
        await pipedreamRuntime.proxy({
          owner,
          app: 'google_calendar',
          url: probe,
          method: 'GET',
        });
        return {
          status: protectedAction ? 'PROTECTED' : 'HEALTHY',
          transport: 'pipedream',
          native_reason: String(nativeError?.code || nativeError?.message || '').slice(0, 160),
        };
      } catch (fallbackError) {
        return {
          status: 'UNAVAILABLE',
          reason: String(fallbackError?.code || fallbackError?.message || 'GOOGLE_CALENDAR_ALL_PATHS_FAILED').slice(0, 180),
        };
      }
    }
  };
}

async function tasksRequest({
  resolveAccessToken,
  fetchImpl,
  pipedreamRuntime,
  env,
  context,
  url,
  method = 'GET',
  body,
  code,
} = {}) {
  let nativeError = null;
  try {
    const token = await tokenFor(resolveAccessToken, 'google-tasks', context);
    const result = await requestJson(fetchImpl, token, url, {
      method,
      body,
      code,
      signal: context?.signal,
    });
    return { provider: 'google', body: result };
  } catch (error) {
    nativeError = error;
  }

  if (!pipedreamRuntime || typeof pipedreamRuntime.proxy !== 'function') throw nativeError;
  try {
    const proxied = await pipedreamRuntime.proxy({
      owner: context?.owner || env?.MELITURGOS_USER || 'owner',
      app: 'google_tasks',
      url,
      method,
      body,
      signal: context?.signal,
    });
    return { provider: 'pipedream', body: proxied?.body || {} };
  } catch (fallbackError) {
    const combined = error(code + '_ALL_PATHS_FAILED', 503);
    combined.native_code = String(nativeError?.code || nativeError?.message || 'GOOGLE_TASKS_NATIVE_FAILED').slice(0, 160);
    combined.fallback_code = String(fallbackError?.code || fallbackError?.message || 'GOOGLE_TASKS_PIPEDREAM_FAILED').slice(0, 160);
    throw combined;
  }
}

function tasksHealthcheck(resolveAccessToken, fetchImpl, env, pipedreamRuntime, { protectedAction = false } = {}) {
  const owner = String(env?.MELITURGOS_USER || 'owner').trim() || 'owner';
  const probe = TASKS_API + '/users/@me/lists?maxResults=1';
  return async () => {
    try {
      const token = await tokenFor(resolveAccessToken, 'google-tasks', { owner });
      await requestJson(fetchImpl, token, probe, { method: 'GET', code: 'GOOGLE_TASKS_HEALTH_FAILED' });
      return { status: protectedAction ? 'PROTECTED' : 'HEALTHY', transport: 'google' };
    } catch (nativeError) {
      if (!pipedreamRuntime || typeof pipedreamRuntime.proxy !== 'function') {
        return {
          status: 'UNAVAILABLE',
          reason: String(nativeError?.code || nativeError?.message || 'GOOGLE_TASKS_HEALTH_FAILED').slice(0, 180),
        };
      }
      try {
        await pipedreamRuntime.proxy({
          owner,
          app: 'google_tasks',
          url: probe,
          method: 'GET',
        });
        return {
          status: protectedAction ? 'PROTECTED' : 'HEALTHY',
          transport: 'pipedream',
          native_reason: String(nativeError?.code || nativeError?.message || '').slice(0, 160),
        };
      } catch (fallbackError) {
        return {
          status: 'UNAVAILABLE',
          reason: String(fallbackError?.code || fallbackError?.message || 'GOOGLE_TASKS_ALL_PATHS_FAILED').slice(0, 180),
        };
      }
    }
  };
}


const GMAIL_TOKEN_CONNECTORS = ['gmail', 'google-calendar', 'google-drive', 'google-tasks'];

function gmailAuthFailure(cause) {
  const code = String(cause?.code || '');
  const http = Number(cause?.status || 0);
  return http === 401 || http === 403 || /AUTH_REQUIRED|_AUTH$/.test(code);
}

async function gmailNativeRead({ resolveAccessToken, fetchImpl, context, url, method, body, code }) {
  for (const connectorId of GMAIL_TOKEN_CONNECTORS) {
    try {
      const token = await tokenFor(resolveAccessToken, connectorId, context);
      const result = await requestJson(fetchImpl, token, url, { method, body, code, signal: context?.signal });
      return { provider: 'google', body: result };
    } catch (cause) {
      if (gmailAuthFailure(cause)) continue;
      throw cause;
    }
  }
  // All four token sources were tried and none authorized Gmail. Returning
  // the last *other-service* error (e.g. GOOGLE_TASKS_AUTH_REQUIRED) hides the
  // actual missing Gmail authorization and blocks the founder proof forever.
  // A non-auth network/timeout failure has already been thrown above.
  throw error('GMAIL_AUTH_REQUIRED', 503);
}

async function gmailRequest({
  resolveAccessToken,
  fetchImpl,
  pipedreamRuntime,
  env,
  context,
  url,
  method = 'GET',
  body,
  code,
  provider = null,
} = {}) {
  const owner = context?.owner || env?.MELITURGOS_USER || 'owner';
  const viaPipedream = async () => {
    if (!pipedreamRuntime || typeof pipedreamRuntime.proxy !== 'function') return null;
    const proxied = await pipedreamRuntime.proxy({ owner, app: 'gmail', url, method, body, signal: context?.signal });
    return { provider: 'pipedream', body: proxied?.body || {} };
  };
  if (provider === 'pipedream') {
    const proxied = await viaPipedream();
    if (!proxied) throw error('PIPEDREAM_RUNTIME_UNAVAILABLE', 503);
    return proxied;
  }
  let nativeError = null;
  try {
    return await gmailNativeRead({ resolveAccessToken, fetchImpl, context, url, method, body, code });
  } catch (error_) {
    nativeError = error_;
  }
  try {
    const proxied = await viaPipedream();
    if (!proxied) throw nativeError;
    return proxied;
  } catch (fallbackError) {
    if (!pipedreamRuntime || typeof pipedreamRuntime.proxy !== 'function') throw nativeError;
    const combined = error(code + '_ALL_PATHS_FAILED', 503);
    combined.native_code = String(nativeError?.code || nativeError?.message || 'GMAIL_NATIVE_FAILED').slice(0, 160);
    combined.fallback_code = String(fallbackError?.code || fallbackError?.message || 'GMAIL_PIPEDREAM_FAILED').slice(0, 160);
    throw combined;
  }
}

function gmailHealthcheck(resolveAccessToken, fetchImpl, env, pipedreamRuntime, { protectedAction = false } = {}) {
  const owner = String(env?.MELITURGOS_USER || 'owner').trim() || 'owner';
  const probe = GMAIL_API + '/profile';
  return async () => {
    try {
      await gmailNativeRead({
        resolveAccessToken, fetchImpl, context: { owner }, url: probe, method: 'GET', code: 'GMAIL_HEALTH_FAILED',
      });
      return { status: protectedAction ? 'PROTECTED' : 'HEALTHY', transport: 'google' };
    } catch (nativeError) {
      if (!pipedreamRuntime || typeof pipedreamRuntime.proxy !== 'function') {
        const code = String(nativeError?.code || nativeError?.message || 'GMAIL_HEALTH_FAILED').slice(0, 180);
        const http = Number(nativeError?.status || 0);
        const unavailable = http === 401 || http === 403 || /AUTH_REQUIRED|_AUTH$/.test(code);
        return { status: unavailable ? 'UNAVAILABLE' : 'DEGRADED', reason: code };
      }
      try {
        await pipedreamRuntime.proxy({ owner, app: 'gmail', url: probe, method: 'GET' });
        return {
          status: protectedAction ? 'PROTECTED' : 'HEALTHY',
          transport: 'pipedream',
          native_reason: String(nativeError?.code || nativeError?.message || '').slice(0, 160),
        };
      } catch (fallbackError) {
        const reason = String(fallbackError?.code || fallbackError?.message || 'GMAIL_ALL_PATHS_FAILED').slice(0, 180);
        const accountMissing = /ACCOUNT_REQUIRED$/.test(reason);
        return { status: accountMissing ? 'DEGRADED' : 'UNAVAILABLE', reason };
      }
    }
  };
}

export function registerGoogleWorkspaceCapabilities(bus, { env = {}, fetchImpl = fetch, resolveAccessToken = null, pipedreamRuntime = null } = {}) {
  if (!bus || typeof bus.discover !== 'function') throw new TypeError('CAPABILITY_BUS_REQUIRED');
  const resolveToken = resolveAccessToken || fixedTokenResolver(env);

  bus.discover({
    id: 'gmail.messages.search',
    name: 'Gmail message search',
    category: 'communication',
    version: '1.0.0',
    provider: 'google',
    description: 'Searches Gmail with a bounded Gmail query and returns subject, sender, date and snippet of the first messages (never the body).',
    input_schema: {
      type: 'object',
      properties: {
        query: { type: 'string', minLength: 1, maxLength: 1000 },
        limit: { type: 'integer', minimum: 1, maximum: MAX_LIST },
      },
      required: ['query'],
      additionalProperties: false,
    },
    output_schema: objectOutput,
    risk: 'LOW',
    permissions: ['google.gmail.read'],
    health: 'DEGRADED',
    healthcheck: gmailHealthcheck(resolveToken, fetchImpl, env, pipedreamRuntime),
    enabled: true,
  }, async (input, context) => {
    const q = text(input.query, 'GMAIL_QUERY_INVALID', 1000);
    const url = GMAIL_API + '/messages?' + query({ q, maxResults: listLimit(input.limit) });
    const listed = await gmailRequest({
      resolveAccessToken: resolveToken, fetchImpl, pipedreamRuntime, env, context, url, code: 'GMAIL_SEARCH_FAILED',
    });
    const body = listed.body || {};
    const ids = (Array.isArray(body.messages) ? body.messages : []).slice(0, listLimit(input.limit)).map(row => ({
      id: String(row.id || ''),
      thread_id: String(row.threadId || ''),
    }));
    // Identifiers alone are useless in a conversation: add subject, sender,
    // date and Gmail's short snippet for the first messages (metadata only,
    // never the body). A failed header read keeps the bare identifier.
    const headerFor = (headers, name) => String((Array.isArray(headers) ? headers : []).find(h => String(h?.name || '').toLowerCase() === name)?.value || '').slice(0, 300);
    const messages = await Promise.all(ids.map(async (row, index) => {
      if (index >= GMAIL_SEARCH_METADATA_MAX || !row.id) return row;
      try {
        const metaResult = await gmailRequest({
          resolveAccessToken: resolveToken, fetchImpl, pipedreamRuntime, env, context,
          url: GMAIL_API + '/messages/' + encodeURIComponent(row.id) + '?format=metadata&metadataHeaders=Subject&metadataHeaders=From&metadataHeaders=Date',
          code: 'GMAIL_METADATA_FAILED', provider: listed.provider,
        });
        const meta = metaResult.body;
        const headers = meta?.payload?.headers;
        return {
          ...row,
          subject: headerFor(headers, 'subject'),
          from: headerFor(headers, 'from'),
          date: headerFor(headers, 'date'),
          snippet: String(meta?.snippet || '').slice(0, 300),
          unread: Array.isArray(meta?.labelIds) ? meta.labelIds.includes('UNREAD') : null,
        };
      } catch (cause) {
        // MEL-MANIFEST-08: a message whose headers could not be read is not a
        // rendered message; keep its exact error code instead of a bare id.
        return { ...row, metadata_error: String(cause?.code || cause?.message || 'GMAIL_METADATA_FAILED').slice(0, 160) };
      }
    }));
    const rendered = messages.filter(row => !row.metadata_error && row.subject !== undefined).length;
    return { provider: listed.provider, query: q, messages, count: messages.length, rendered };
  });

  bus.discover({
    id: 'gmail.messages.read',
    name: 'Gmail message read',
    category: 'communication',
    version: '1.0.0',
    provider: 'google',
    description: 'Reads one Gmail message by fixed message id.',
    input_schema: {
      type: 'object',
      properties: { message_id: { type: 'string', minLength: 1, maxLength: 300 } },
      required: ['message_id'],
      additionalProperties: false,
    },
    output_schema: objectOutput,
    risk: 'LOW',
    permissions: ['google.gmail.read'],
    health: 'DEGRADED',
    healthcheck: gmailHealthcheck(resolveToken, fetchImpl, env, pipedreamRuntime),
    enabled: true,
  }, async (input, context) => {
    const id = encodePath(input.message_id, 'GMAIL_MESSAGE_ID_INVALID');
    const read = await gmailRequest({
      resolveAccessToken: resolveToken, fetchImpl, pipedreamRuntime, env, context,
      url: GMAIL_API + '/messages/' + id + '?format=full', code: 'GMAIL_READ_FAILED',
    });
    return { provider: read.provider, message: read.body };
  });

  for (const [id, draft, approvalScope] of [
    ['gmail.drafts.create', true, 'gmail.drafts.create'],
    ['gmail.messages.send', false, 'gmail.messages.send'],
  ]) {
    bus.discover({
      id,
      name: draft ? 'Gmail draft create' : 'Gmail send message',
      category: 'communication',
      version: '1.0.0',
      provider: 'google',
      description: draft
        ? 'Creates one bounded Gmail draft after explicit owner approval.'
        : 'Sends one bounded plain-text Gmail message after explicit owner approval.',
      input_schema: {
        type: 'object',
        properties: {
          to: { type: 'array', minItems: 1, maxItems: 20, items: { type: 'string', minLength: 3, maxLength: 320 } },
          cc: { type: 'array', maxItems: 20, items: { type: 'string', minLength: 3, maxLength: 320 } },
          bcc: { type: 'array', maxItems: 20, items: { type: 'string', minLength: 3, maxLength: 320 } },
          subject: { type: 'string', minLength: 1, maxLength: 998 },
          body: { type: 'string', minLength: 1, maxLength: 100000 },
        },
        required: ['to', 'subject', 'body'],
        additionalProperties: false,
      },
      output_schema: objectOutput,
      risk: draft ? 'MEDIUM' : 'HIGH',
      permissions: [draft ? 'google.gmail.draft' : 'google.gmail.send'],
      approval: { required: true, scope: approvalScope, reason: draft ? 'GMAIL_DRAFT_MUTATION' : 'GMAIL_SEND_MUTATION' },
      health: 'DEGRADED',
    healthcheck: workspaceHealthcheck(resolveToken, fetchImpl, env, 'gmail', { protectedAction: true }),
      enabled: true,
    }, async (input, context) => {
      const token = await tokenFor(resolveToken, 'gmail', context);
      const raw = mimeMessage(input);
      const endpoint = draft ? GMAIL_API + '/drafts' : GMAIL_API + '/messages/send';
      const body = await requestJson(fetchImpl, token, endpoint, {
        method: 'POST',
        body: draft ? { message: { raw } } : { raw },
        code: draft ? 'GMAIL_DRAFT_CREATE_FAILED' : 'GMAIL_SEND_FAILED',
        signal: context?.signal,
      });
      return {
        provider: 'google',
        accepted: true,
        draft_id: draft ? String(body.id || '') : '',
        message_id: draft ? String(body.message?.id || '') : String(body.id || ''),
        thread_id: draft ? String(body.message?.threadId || '') : String(body.threadId || ''),
      };
    });
  }

  bus.discover({
    id: 'calendar.events.read',
    name: 'Google Calendar event search',
    category: 'planning',
    version: '1.1.0',
    provider: 'google+pipedream',
    description: 'Reads a bounded set of events from one Google calendar, using native Google first and the linked Pipedream account as an authenticated fallback.',
    input_schema: {
      type: 'object',
      properties: {
        calendar_id: { type: 'string', minLength: 1, maxLength: 300 },
        time_min: { type: 'string', maxLength: 80 },
        time_max: { type: 'string', maxLength: 80 },
        query: { type: 'string', maxLength: 1000 },
        limit: { type: 'integer', minimum: 1, maximum: MAX_LIST },
      },
      additionalProperties: false,
    },
    output_schema: objectOutput,
    risk: 'LOW',
    permissions: ['google.calendar.read'],
    health: 'DEGRADED',
    healthcheck: calendarHealthcheck(resolveToken, fetchImpl, env, pipedreamRuntime),
    enabled: true,
  }, async (input, context) => {
    const calendarId = encodeURIComponent(text(input.calendar_id || 'primary', 'CALENDAR_ID_INVALID', 300));
    const params = query({
      singleEvents: 'true',
      orderBy: 'startTime',
      maxResults: listLimit(input.limit),
      timeMin: input.time_min ? text(input.time_min, 'CALENDAR_TIME_INVALID', 80) : '',
      timeMax: input.time_max ? text(input.time_max, 'CALENDAR_TIME_INVALID', 80) : '',
      q: input.query ? text(input.query, 'CALENDAR_QUERY_INVALID', 1000) : '',
    });
    const transport = await calendarRequest({
      resolveAccessToken: resolveToken,
      fetchImpl,
      pipedreamRuntime,
      env,
      context,
      url: CALENDAR_API + '/calendars/' + calendarId + '/events?' + params,
      code: 'CALENDAR_READ_FAILED',
    });
    const events = (Array.isArray(transport.body?.items) ? transport.body.items : []).slice(0, listLimit(input.limit));
    return {
      provider: transport.provider,
      calendar_id: input.calendar_id || 'primary',
      events,
      count: events.length,
    };
  });

  for (const spec of [
    { id: 'calendar.events.create', method: 'POST', action: 'create', permission: 'google.calendar.write', risk: 'HIGH' },
    { id: 'calendar.events.update', method: 'PATCH', action: 'update', permission: 'google.calendar.write', risk: 'HIGH' },
    { id: 'calendar.events.delete', method: 'DELETE', action: 'delete', permission: 'google.calendar.delete', risk: 'HIGH' },
  ]) {
    bus.discover({
      id: spec.id,
      name: 'Google Calendar event ' + spec.action,
      category: 'planning',
      version: '1.1.0',
      provider: 'google+pipedream',
      description: 'Mutates one Google Calendar event after explicit owner approval, using native Google first and Pipedream only as an authenticated fallback.',
      input_schema: {
        type: 'object',
        properties: {
          calendar_id: { type: 'string', minLength: 1, maxLength: 300 },
          event_id: { type: 'string', minLength: 1, maxLength: 300 },
          summary: { type: 'string', maxLength: 1000 },
          description: { type: 'string', maxLength: 12000 },
          location: { type: 'string', maxLength: 1000 },
          start: { type: 'string', maxLength: 80 },
          end: { type: 'string', maxLength: 80 },
          timeZone: { type: 'string', maxLength: 100 },
          attendees: { type: 'array', maxItems: 50, items: { type: 'string', minLength: 3, maxLength: 320 } },
        },
        ...(spec.action === 'create' ? { required: ['summary', 'start', 'end'] } : { required: ['event_id'] }),
        additionalProperties: false,
      },
      output_schema: objectOutput,
      risk: spec.risk,
      permissions: [spec.permission],
      approval: { required: true, scope: spec.id, reason: 'CALENDAR_EVENT_MUTATION' },
      health: 'DEGRADED',
      healthcheck: calendarHealthcheck(resolveToken, fetchImpl, env, pipedreamRuntime, { protectedAction: true }),
      enabled: true,
    }, async (input, context) => {
      const calendarId = encodeURIComponent(text(input.calendar_id || 'primary', 'CALENDAR_ID_INVALID', 300));
      const base = CALENDAR_API + '/calendars/' + calendarId + '/events';
      let url = base;
      let body;
      if (spec.action === 'create') body = calendarEvent(input);
      else {
        const eventId = encodePath(input.event_id, 'CALENDAR_EVENT_ID_INVALID');
        url += '/' + eventId;
        if (spec.action === 'update') body = calendarEvent(input, { partial: true });
      }
      const transport = await calendarRequest({
        resolveAccessToken: resolveToken,
        fetchImpl,
        pipedreamRuntime,
        env,
        context,
        url,
        method: spec.method,
        body,
        code: 'CALENDAR_' + spec.action.toUpperCase() + '_FAILED',
      });
      return {
        provider: transport.provider,
        calendar_id: input.calendar_id || 'primary',
        event_id: String(transport.body?.id || input.event_id || ''),
        accepted: true,
      };
    });
  }

  bus.discover({
    id: 'tasks.tasklists.read',
    name: 'Google Tasks lists read',
    category: 'planning',
    version: '1.0.0',
    provider: 'google+pipedream',
    description: 'Lists bounded Google Tasks task lists, using native Google first and the linked Pipedream account as fallback.',
    input_schema: {
      type: 'object',
      properties: { limit: { type: 'integer', minimum: 1, maximum: MAX_LIST } },
